-- Paket 13.11.2026: cart quantity buttons (chunk 17) + mobile filters (new chunk, template 18). Text is hex-encoded on purpose.
SET NAMES utf8mb4;
SET SESSION group_concat_max_len = 100000;
-- APPLY. Saves the originals to hts_bak_20261113 first; safe to run twice.
CREATE TABLE IF NOT EXISTS hts_bak_20261113 (kind VARCHAR(16) NOT NULL, el_id INT NOT NULL, body MEDIUMTEXT, saved_at DATETIME NOT NULL, PRIMARY KEY (kind, el_id)) DEFAULT CHARSET=utf8mb4;
INSERT IGNORE INTO hts_bak_20261113 (kind, el_id, body, saved_at) SELECT 'chunk', c.id, c.snippet, NOW() FROM modx_site_htmlsnippets c WHERE c.id = 17 AND c.name = 'tpl.msCart' AND c.snippet NOT LIKE '%hts-qty-btn%';
INSERT IGNORE INTO hts_bak_20261113 (kind, el_id, body, saved_at) SELECT 'template', t.id, t.content, NOW() FROM modx_site_templates t WHERE t.id = 18 AND t.content NOT LIKE '%[[$HtsMobileFilters]]%';
