WHERE c.id = 17 AND c.name = 'tpl.msCart' AND c.snippet NOT LIKE '%hts-qty-btn%' AND ROUND((CHAR_LENGTH(CONVERT(c.snippet USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(c.snippet USING utf8mb4), _utf8mb4 0x3C666F726D206D6574686F643D22706F73742220636C6173733D226D73325F666F726D22207374796C653D22646973706C61793A666C657821696D706F7274616E743B616C69676E2D6974656D733A63656E74657221696D706F7274616E743B6761703A36707821696D706F7274616E743B6D617267696E3A3021696D706F7274616E74223E, ''))) / 134) = 1 AND ROUND((CHAR_LENGTH(CONVERT(c.snippet USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(c.snippet USING utf8mb4), _utf8mb4 , ''))) / 254) = 1 AND ROUND((CHAR_LENGTH(CONVERT(c.snippet USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(c.snippet USING utf8mb4), _utf8mb4 0x2428646F63756D656E74292E72656164792866756E6374696F6E28297B20242822236D734361727420696E7075745B747970653D6E756D6265725D22292E7374657070657228293B207D293B, ''))) / 76) = 1 AND ROUND((CHAR_LENGTH(CONVERT(c.snippet USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(c.snippet USING utf8mb4), _utf8mb4 0x3C2F7374796C653E, ''))) / 8) = 1;
UPDATE modx_site_templates t SET t.content = REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x5B5B24636F6E74656E7463617465676F72795D5D, _utf8mb4 0x5B5B24636F6E74656E7463617465676F72795D5D0A2020202020202020202020202020202020202020202020205B5B244874734D6F62696C6546696C746572735D5D)
WHERE t.id = 18 AND t.templatename = _utf8mb4 0xD09FD0BED0B4D0BAD0B0D182D0B5D0B3D0BED180D0B8D18F AND t.content NOT LIKE '%[[$HtsMobileFilters]]%' AND ROUND((CHAR_LENGTH(CONVERT(t.content USING utf8mb4)) - CHAR_LENGTH(REPLACE(CONVERT(t.content USING utf8mb4), _utf8mb4 0x5B5B24636F6E74656E7463617465676F72795D5D, ''))) / 20) = 1;
INSERT INTO modx_site_htmlsnippets (source, name, description, category, snippet, properties, static, static_file)
SELECT 1, 'HtsMobileFilters', _utf8mb4 0xD09AD0BDD0BED0BFD0BAD0B020C2ABD0A4D0B8D0BBD18CD182D180D18BC2BB20D0B820D0BFD0B0D0BDD0B5D0BBD18C20D184D0B8D0BBD18CD182D180D0BED0B220D0BDD0B020D182D0B5D0BBD0B5D184D0BED0BDD0B5, 0, _utf8mb4 , 'a:0:{}', 0, '' FROM (SELECT 1 AS x) d
WHERE NOT EXISTS (SELECT 1 FROM modx_site_htmlsnippets WHERE name = 'HtsMobileFilters');
-- RESULT: expect 3 x DONE.
SELECT itog, COUNT(*) AS n, GROUP_CONCAT(chto ORDER BY chto SEPARATOR '; ') AS what FROM (
